/**
 * @name User-controlled regex compilation
 * @description Taint tracking from public API parameters to re.compile, indicating potential ReDoS or Regex Injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/pathspec-regex-injection
 * @tags security
 *       external/cwe/cwe-1333
 *       external/cwe/cwe-730
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider parameters of public methods/functions as sources for a library
    exists(Function f |
      f.getScope().getEnclosingModule().getName().matches("pathspec%") and
      not f.getName().matches("_%") and // Exclude private methods
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember("compile").getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential ReDoS/Regex Injection from $@.", source.getNode(), "library input"
